class Solution:
    def maxAlternatingSubarray(self, nums):
        n = len(nums)
        def best(arr):
            m, ans = len(arr), 1
            for i in range(m):
                l = 1
                for j in range(i + 1, m):
                    a = (arr[j] > arr[j - 1]) - (arr[j] < arr[j - 1])
                    b = (arr[j - 1] > arr[j - 2]) - (arr[j - 1] < arr[j - 2]) if j > i + 1 else 0
                    if a == 0 or (j > i + 1 and a == b):
                        break
                    l += 1
                ans = max(ans, l)
            return ans
        return max(best(nums[:p] + nums[p + 1:]) for p in range(-1, n))

