class Solution {
public:
    int maxAlternatingSubarray(vector<int>& nums) {
        int n = nums.size(), ans = 1;
        auto sgn = [](long long x) { return x > 0 ? 1 : (x < 0 ? -1 : 0); };
        for (int p = -1; p < n; p++) {
            vector<int> a;
            for (int i = 0; i < n; i++) if (i != p) a.push_back(nums[i]);
            int m = a.size();
            for (int i = 0; i < m; i++) {
                int len = 1;
                for (int j = i + 1; j < m; j++) {
                    int cur = sgn((long long)a[j] - a[j - 1]);
                    int prev = j > i + 1 ? sgn((long long)a[j - 1] - a[j - 2]) : 0;
                    if (cur == 0 || (j > i + 1 && cur == prev)) break;
                    len++;
                }
                ans = max(ans, len);
            }
        }
        return ans;
    }
};

