class Solution:
    def maxAlternatingSubarray(self, nums):
        n = len(nums)
        def sg(a, b):
            return (a > b) - (a < b)
        endL = [1] * n; endS = [0] * n
        for i in range(1, n):
            d = sg(nums[i], nums[i - 1])
            if d != 0 and (endL[i - 1] == 1 or d == -endS[i - 1]):
                endL[i] = endL[i - 1] + 1; endS[i] = d
        startL = [1] * n; startS = [0] * n
        for i in range(n - 2, -1, -1):
            d = sg(nums[i + 1], nums[i])
            if d != 0 and (startL[i + 1] == 1 or d == -startS[i + 1]):
                startL[i] = startL[i + 1] + 1; startS[i] = d
        ans = max(endL)
        for p in range(1, n - 1):
            a = sg(nums[p + 1], nums[p - 1])
            if a == 0:
                continue
            if (endL[p - 1] == 1 or endS[p - 1] != a) and \
               (startL[p + 1] == 1 or startS[p + 1] == a):
                ans = max(ans, endL[p - 1] + startL[p + 1])
        return ans

