    const sg = (a, b) => a > b ? 1 : (a < b ? -1 : 0);
    const endL = new Array(n).fill(1), endS = new Array(n).fill(0);
    const startL = new Array(n).fill(1), startS = new Array(n).fill(0);
    for (let i = 1; i < n; i++) {
        const d = sg(nums[i], nums[i - 1]);
        if (d !== 0 && (endL[i - 1] === 1 || d === -endS[i - 1])) {
            endL[i] = endL[i - 1] + 1; endS[i] = d;
        }
    }
    for (let i = n - 2; i >= 0; i--) {
        const d = sg(nums[i + 1], nums[i]);
        if (d !== 0 && (startL[i + 1] === 1 || d === -startS[i + 1])) {
            startL[i] = startL[i + 1] + 1; startS[i] = d;
        }
    }
    let ans = Math.max(...endL);
    for (let p = 1; p + 1 < n; p++) {
        const a = sg(nums[p + 1], nums[p - 1]);
        if (a === 0) continue;
